import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type LiquidTransitionProps = Record<string, any>;

// Helper function to generate a smooth, liquid-like wavy path
const getLiquidPath = (
  D: number,
  segments: number,
  frame: number,
  amplitude: number,
  speed: number,
  frequency: number,
  phaseOffset: number
) => {
  const step = (2 * D) / segments;
  let path = `M ${-D} 0`;

  for (let i = 0; i < segments; i++) {
    const startX = -D + i * step;
    const endX = startX + step;
    
    // Control points for cubic bezier
    const cx1 = startX + step / 3;
    const cx2 = endX - step / 3;

    // Organic amplitude variation to break up perfect sine waves
    const organicAmp1 = amplitude * (0.8 + 0.4 * Math.sin(cx1 * 0.005 + phaseOffset));
    const organicAmp2 = amplitude * (0.8 + 0.4 * Math.sin(cx2 * 0.005 + phaseOffset));

    // Y offsets for the liquid wobble
    const cy1 = organicAmp1 * Math.sin((cx1 / D) * Math.PI * frequency + frame * speed + phaseOffset);
    const cy2 = organicAmp2 * Math.sin((cx2 / D) * Math.PI * frequency + frame * speed + phaseOffset);

    path += ` C ${cx1} ${cy1}, ${cx2} ${cy2}, ${endX} 0`;
  }

  // Complete the solid block that follows the wavy edge
  path += ` L ${D} ${2 * D} L ${-D} ${2 * D} Z`;
  return path;
};

const LiquidTransition: React.FC<LiquidTransitionProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 4,
  liquidLayers = ["#1e3a8a", "#3b82f6", "#93c5fd", "#ffffff"],
  waveAmplitude = 80,
  waveSpeed = 0.06,
  waveFrequency = 2.5,
  staggerFrames = 12,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Playfair Display"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Math to handle the diagonal movement across the canvas
  const D = useMemo(() => Math.sqrt(width * width + height * height), [width, height]);
  
  // Calculate the required rotation so the wavy edge is perpendicular to the diagonal path
  const rotationDeg = useMemo(() => Math.atan2(width, height) * (180 / Math.PI), [width, height]);

  // Movement vectors and padding to ensure the shape starts completely off-screen
  // and finishes completely covering the screen
  const padding = D * 0.35;
  const startX = -(width / D) * padding;
  const startY = height + (height / D) * padding;
  
  const endX = width + (width / D) * padding;
  const endY = -(height / D) * padding;

  // Calculate the base duration for each layer's movement
  const transitionDurationFrames = Math.max(
    1,
    durationInSeconds * fps - liquidLayers.length * staggerFrames
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Playfair Display", overflow: "hidden" }}>
      <svg 
        width={width} 
        height={height} 
        style={{ overflow: "visible", position: "absolute", top: 0, left: 0 }}
      >
        {liquidLayers.map((color, index) => {
          // Stagger the start time of each layer
          const layerProgress = interpolate(
            frame - index * staggerFrames,
            [0, transitionDurationFrames],
            [0, 1],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.bezier(0.5, 0.0, 0.2, 1),
            }
          );

          // Interpolate position from bottom-left offset to top-right offset
          const currentX = interpolate(layerProgress, [0, 1], [startX, endX]);
          const currentY = interpolate(layerProgress, [0, 1], [startY, endY]);

          // Generate the dynamic SVG path for this frame
          const pathD = getLiquidPath(
            D, 
            8, 
            frame, 
            waveAmplitude, 
            waveSpeed, 
            waveFrequency, 
            index * 45 // Phase offset so layers don't wobble identically
          );

          return (
            <g
              key={index}
              style={{
                transform: `translate(${currentX}px, ${currentY}px) rotate(${rotationDeg}deg)`,
                transition: "none",
              }}
            >
              <path 
                d={pathD} 
                fill={color} 
                style={{ transition: "none" }} 
              />
            </g>
          );
        })}
      </svg>
    </AbsoluteFill>
  );
};

export default LiquidTransition;